mapper.select:
SELECT


WHERE e.deleted = 0

    AND o.store_id = #{q.storeId}


    AND e.rating = #{q.rating}


    AND e.status = #{q.status}


    AND (e.reply IS NULL OR e.reply = '')


    AND (
        o.order_no LIKE CONCAT('%', #{q.keyword}, '%')
        OR u.username LIKE CONCAT('%', #{q.keyword}, '%')
        OR u.real_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR e.content LIKE CONCAT('%', #{q.keyword}, '%')
    )

ORDER BY e.create_time DESC, e.id DESC
